    /// Total returns the order's total, after the discount on lines of at least
    /// MinQty items.
    fn total_go(&self) -> Result<i64, Iface> {
        self.validate_go()?;
        let mut total: i64 = 0;
        for l in &self.lines {
            let mut c = l.quantity * l.price;
            if l.quantity >= self.min_qty {
                c -= c * self.percent / 100;
            }
            total += c;
        }
        Ok(total)
    }

    /// Total returns the order's total, after the discount on lines of at least
    /// MinQty items.
    pub fn total(&self) -> Result<i64, Error> {
        self.total_go().map_err(Error)
    }
