/// Label names a line.
pub fn label(l: &Line) -> String {
    format!("{} x{} at {}", l.sku, l.quantity, l.price)
}

/// Bulk returns the lines of at least min items, in order.
pub fn bulk(lines: &[Line], min: i64) -> Vec<Line> {
    let mut out: Vec<Line> = Vec::new();
    for l in lines {
        if l.quantity >= min {
            out.push(l.clone());
        }
    }
    out
}

/// Tag keeps a note on the order and returns its label.
pub fn tag(mut o: Order, note: String) -> String {
    o.note = note.clone();
    format!("{}: {}", note, format!("{}", o.lines.len() as i64))
}

/// Reprice returns the lines with every price changed by deltaCents, and an
/// error for a price that would fall below zero.
fn reprice_go(
    lines: &[Line],
    delta_cents: i64,
    minimum_quantity: i64,
    keep_unchanged: bool,
) -> Result<Vec<Line>, Iface> {
    let mut out: Vec<Line> = Vec::new();
    for l in lines.iter() {
        let mut l = l.clone();
        if l.quantity >= minimum_quantity || !keep_unchanged {
            l.price += delta_cents;
        }
        if l.price < 0 {
            return Err(go_error(format!("{}: price below zero", l.sku)));
        }
        out.push(l);
    }
    Ok(out)
}

/// Reprice returns the lines with every price changed by deltaCents, and an
/// error for a price that would fall below zero.
pub fn reprice(
    lines: &[Line],
    delta_cents: i64,
    minimum_quantity: i64,
    keep_unchanged: bool,
) -> Result<Vec<Line>, Error> {
    reprice_go(lines, delta_cents, minimum_quantity, keep_unchanged).map_err(Error)
}

